export function Pattern({
  kind = "{{kind}}",
  accent = "{{accent}}",
  showNumbers = {{showNumbers}},
}) {
  const steps = {
    confirmation: ["User clicks Delete", "A dialog asks to confirm", "Action proceeds only after Yes"],
    "progressive-disclosure": ["Summary shown by default", '"Show more" reveals detail', "Advanced options stay hidden until asked for"],
  }[kind];
  const Tag = showNumbers ? "ol" : "ul";
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430" }}>
      <Tag style={{ margin: 0, paddingLeft: showNumbers ? 20 : 0, listStyle: showNumbers ? "decimal" : "none" }}>
        {steps.map((s) => (
          <li key={s} style={{ padding: "6px 0", borderBottom: "1px dashed #24143022" }}>{s}</li>
        ))}
      </Tag>
      <p style={{ margin: "12px 0 0", fontSize: 12, color: "#241430aa" }}>A reusable solution &mdash; the {kind} pattern, applied wherever it fits</p>
    </div>
  );
}
